"""Household records surface; server values are written as text, never markup."""
from __future__ import annotations

import html

CSS = r"""
#myThingsSetting{padding:12px 18px;border:1px solid var(--border,#c7cfd8);border-radius:10px;margin:12px;display:flex;align-items:center;gap:12px}#myThingsSetting input{width:auto}
#thingsLink{display:inline-flex;padding:8px 12px;border:1px solid var(--border,#c7cfd8);border-radius:8px;color:inherit;text-decoration:none;margin:6px}
.mt-page{font:16px/1.5 system-ui,sans-serif;max-width:1060px;margin:0 auto;padding:32px 24px;color:#21332f;background:#f7f8f4;min-height:100vh;box-sizing:border-box}
.mt-page *{box-sizing:border-box}.mt-page h1{font-size:34px;letter-spacing:-1px;margin:0}.mt-page h2{font-size:21px;margin:0 0 12px}.mt-page p{color:#50635c}.mt-bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}
.mt-page button,.mt-page .mt-link{font:inherit;background:#fff;color:#214c40;border:1px solid #a9bdb2;border-radius:9px;padding:9px 14px;cursor:pointer;text-decoration:none}.mt-page button:hover{background:#edf2e9}.mt-page button:focus-visible,.mt-page input:focus-visible,.mt-page textarea:focus-visible{outline:3px solid #b0812b;outline-offset:2px}.mt-page button:disabled{opacity:.5;cursor:wait}.mt-page .mt-primary{background:#275846;color:white}.mt-page .mt-danger{color:#8c302e;border-color:#c68b84}
.mt-grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:22px}.mt-card{border:1px solid #c9d4c8;border-radius:16px;background:#fff;padding:22px;min-width:0}.mt-list{display:flex;flex-direction:column;gap:8px}.mt-list button{text-align:start}.mt-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mt-form label{display:flex;flex-direction:column;font-size:14px;gap:4px}.mt-page input,.mt-page textarea,.mt-page select{font:inherit;border:1px solid #a9bdb2;border-radius:7px;padding:9px;width:100%;background:#fff;color:#21332f}.mt-page textarea{min-height:78px;resize:vertical}.mt-wide{grid-column:1/-1}.mt-page pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;background:#f3f5ef;border-radius:9px;padding:12px}.mt-status{min-height:28px;color:#50635c;overflow-wrap:anywhere}.mt-status[data-error="true"]{color:#923729}.mt-muted{font-size:14px;color:#60726a}.mt-file{display:flex;gap:10px;flex-wrap:wrap;align-items:center;border-top:1px solid #e1e7de;padding:8px 0}.mt-file input{max-width:300px}.mt-page [hidden]{display:none!important}
@media(max-width:680px){.mt-page{padding:20px 14px}.mt-grid{grid-template-columns:1fr}.mt-form{grid-template-columns:1fr}.mt-card{padding:16px}.mt-page h1{font-size:28px}}
"""

JS = r"""
(function(){'use strict';
const append=(parent,...nodes)=>nodes.forEach(node=>parent.appendChild(node));
const prepend=(parent,...nodes)=>nodes.reverse().forEach(node=>parent.insertBefore(node,parent.firstChild));
const t=k=>window.VOOLT('things.'+k), common=k=>window.VOOLT(k);
const root=document.getElementById('myThingsRoot');
if(!root){const link=document.createElement('a');link.id='thingsLink';link.href='/my-things';link.textContent=t('title');const host=document.getElementById('contactsBtn');if(host)host.parentNode.insertBefore(link,host.nextSibling);else{const section=document.createElement('section');section.id='myThingsSetting';const label=document.createElement('label');label.textContent=t('title')+' ';const toggle=document.createElement('input');toggle.type='checkbox';toggle.setAttribute('aria-label',t('title'));append(label,toggle);append(section,label,link);prepend(document.querySelector('main')||document.body,section);fetch('/api/my-things/preferences',{cache:'no-store'}).then(r=>r.json()).then(r=>{toggle.checked=r.enabled===true;}).catch(()=>{toggle.disabled=true;});toggle.onchange=async()=>{toggle.disabled=true;try{const res=await fetch('/api/my-things/preferences',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:toggle.checked})});if(!res.ok)toggle.checked=!toggle.checked;}catch(e){toggle.checked=!toggle.checked;}finally{toggle.disabled=false;}};}return;}
let items=[], selected=null, pendingFile=null, busy=false, selectedDraftKind='repair';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(label,fn,cls)=>{const b=el('button',label,cls);b.type='button';b.onclick=()=>task(fn);return b;};
const status=el('div','','mt-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
const list=el('nav','','mt-list');list.setAttribute('aria-label',t('title'));const detail=el('section','','mt-card');
const say=(s,error=false)=>{status.textContent=s||'';status.dataset.error=String(error);};
async function request(action,data){const res=await fetch('/api/my-things'+(action?'/'+action:''),data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),cache:'no-store'});const body=await res.json();if(!res.ok||!body.ok){const e=new Error(body.error||'failed');e.code=body.error;throw e;}return body;}
async function task(fn){if(busy)return;busy=true;say('');const controls=Array.from(root.querySelectorAll('button,input[type=checkbox]')).map(node=>[node,node.disabled]);controls.forEach(pair=>pair[0].disabled=true);try{await fn();}catch(e){say(t(e.code==='online_off'?'online_off':e.code==='disabled'?'disabled':e.code==='stale'?'stale':'retry'),true);}finally{controls.forEach(pair=>{if(pair[0].isConnected)pair[0].disabled=pair[1];});busy=false;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;append(document.body,a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function packet(action,data,name){const res=await fetch('/api/my-things/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!res.ok){throw new Error('download');}download(await res.blob(),name);}
async function fileData(file,kind){if(!file||file.size>8*1024*1024||file.size===0)throw new Error('file');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));return {name:file.name,kind:kind,data:btoa(raw)};}
function fileControl(parent,label,kind,fn){const row=el('div','','mt-file');const input=el('input');input.type='file';input.hidden=true;input.setAttribute('aria-label',label+' · '+t(kind));const choose=el('button',t('choose_file'));choose.type='button';choose.setAttribute('aria-label',t('choose_file')+' · '+label);choose.onclick=()=>input.click();input.onchange=()=>{choose.textContent=input.files.length?input.files[0].name:t('choose_file');};append(row,input,choose,button(label,async()=>{const file=await fileData(input.files[0],kind);input.value='';choose.textContent=t('choose_file');await fn(file);}));append(parent,row);}
function refreshList(){list.textContent='';if(!items.length)append(list,el('p',t('empty'),'mt-muted'));items.forEach(item=>{const b=button(item.name,()=>show(item));b.setAttribute('aria-current',selected&&selected.id===item.id?'true':'false');append(list,b);});}
async function refresh(){items=(await request('')).things;refreshList();}
const fields=['name','maker','model','serial','bought_on','bought_from','price','warranty_end','notes','specs','order_items'];
function form(record){detail.textContent='';append(detail,el('h2',t(record&&record.id?'edit':'add')));const form=el('form','','mt-form'),inputs={};fields.forEach(key=>{const label=el('label',t(key));const input=el(['notes','specs','order_items'].includes(key)?'textarea':'input');input.name=key;input.id='mt-'+key;input.value=record&&record[key]||'';if(key==='bought_on'||key==='warranty_end')input.type='date';if(key==='name')input.required=true;if(input.tagName==='TEXTAREA')label.className='mt-wide';inputs[key]=input;append(label,input);append(form,label);});
const bar=el('div','','mt-bar mt-wide');const save=el('button',common('notif.save'),'mt-primary');save.type='submit';append(bar,save,button(common('dialog.cancel'),()=>{pendingFile=null;record&&record.id?show(record):welcome();}));append(form,bar);form.onsubmit=e=>{e.preventDefault();task(async()=>{const values={};fields.forEach(key=>values[key]=inputs[key].value);const body={fields:values,confirm:true};if(record&&record.id){body.id=record.id;body.revision=record.revision;}else if(pendingFile)body.file=pendingFile;const res=await request('save',body);pendingFile=null;await refresh();show(res.thing);say(t('saved'));});};append(detail,form);inputs.name.focus();}
function welcome(){selected=null;detail.textContent='';append(detail,el('h2',t(items.length?'saved_things':'empty')),el('p',t(items.length?'choose_saved':'intro')));refreshList();}
function show(record){selected=record;selectedDraftKind='repair';detail.textContent='';append(detail,el('h2',record.name));fields.filter(key=>key!=='name'&&record[key]).forEach(key=>{const line=el('p');append(line,el('strong',t(key)+': '),document.createTextNode(record[key]));append(detail,line);});const bar=el('div','','mt-bar');append(bar,button(t('edit'),()=>form(record)),button(common('dialog.delete'),()=>confirmDelete(record),'mt-danger'));append(detail,bar);
(record.files||[]).forEach(file=>append(detail,button(file.name+' · '+t(file.kind),()=>packet('file',{id:record.id,file_id:file.id},file.name))));
const kind=el('select');['receipt','manual','photo','note'].forEach(key=>{const option=el('option',t(key));option.value=key;append(kind,option);});kind.setAttribute('aria-label',t('attach'));append(detail,kind);fileControl(detail,t('attach'),'note',async(file)=>{file.kind=kind.value;const res=await request('attach',{id:record.id,revision:record.revision,file:file});await refresh();show(res.thing);});
const manualUrl=el('input');manualUrl.type='url';manualUrl.placeholder=t('manual_url');manualUrl.setAttribute('aria-label',t('manual_url'));append(detail,el('p',t('manual_warning'),'mt-muted'),manualUrl,button(t('manual_fetch'),()=>manualPreview(record,manualUrl.value)));
const tools=el('div','','mt-bar');append(tools,button(t('warranty'),async()=>renderResult(await request('prepare',{id:record.id,kind:'warranty'}))));append(detail,tools);const issue=el('textarea');issue.setAttribute('aria-label',t('issue'));issue.placeholder=t('issue');append(detail,issue);const requests=el('div','','mt-bar');['return','repair'].forEach(kind=>append(requests,button(t(kind),async()=>{selectedDraftKind=kind;renderResult(await request('prepare',{id:record.id,kind:kind,issue:issue.value}));})));append(requests,button(t('packet'),async()=>packet('packet',{id:record.id,kind:selectedDraftKind,issue:issue.value},'request-draft.zip')));append(detail,requests);
const observed=el('textarea');observed.setAttribute('aria-label',t('observed'));observed.placeholder=t('observed');append(detail,observed);fileControl(detail,t('read_photo'),'photo',async file=>{const result=await request('read',{file:file});if(result.reading.state!=='read'){say(t(result.reading.state==='unavailable'?'photo_unavailable':'unreadable'));return;}observed.value=result.reading.text;observed.focus();});const compare=el('div','','mt-bar');append(compare,button(t('fits'),async()=>renderResult(await request('prepare',{id:record.id,kind:'fits',observed:observed.value}))),button(t('delivery'),()=>delivery(record,observed.value)));append(detail,compare);refreshList();}
async function manualPreview(record,url){const result=await request('manual',{id:record.id,url:url,confirm:true});let out=detail.querySelector('#mt-manual');if(!out){out=el('section');out.id='mt-manual';append(detail,out);}out.textContent='';append(out,el('p',result.url||url));if(result.requires_approval){append(out,el('p',t('manual_warning')),button(t('manual_fetch'),async()=>{const response=await fetch('/api/mode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'resolve_approval',session_id:result.session_id,approval_id:result.approval_request.approval_id,decision:'allow',scope:'once'})});if(!response.ok)throw new Error('approval');await manualPreview(record,url);}),button(common('dialog.cancel'),async()=>{await fetch('/api/mode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'resolve_approval',session_id:result.session_id,approval_id:result.approval_request.approval_id,decision:'deny',scope:'once'})});out.remove();}));return;}append(out,el('pre',result.text),button(t('manual_save'),async()=>{const chosen=new File([result.text],'manual.txt',{type:'text/plain'});const saved=await request('attach',{id:record.id,revision:record.revision,file:await fileData(chosen,'manual')});await refresh();show(saved.thing);say(t('saved'));}));out.scrollIntoView({block:'nearest'});}
function renderResult(result){let out=detail.querySelector('#mt-result');if(!out){out=el('section');out.id='mt-result';append(detail,out);}out.textContent='';append(out,el('p',t('draft_only'),'mt-muted'));if(result.draft){const draft=el('pre',result.draft);draft.lang=result.draft_language||'en';draft.dir='ltr';append(out,draft);}if(result.warranty)append(out,el('p',t('warranty_'+result.warranty.state)+(result.warranty.end?' · '+result.warranty.end:'')));['matches','conflicts','unknown'].forEach(key=>{let values=result[key]||[];if(key==='unknown')values=values.concat((result.unknown_fields||[]).map(t),(result.unknown_codes||[]).map(t));if(values.length){append(out,el('h3',t(key)));values.forEach(value=>append(out,el('p',value)));}});out.scrollIntoView({block:'nearest'});}
async function delivery(record,observed){const result=await request('prepare',{id:record.id,kind:'delivery',observed:observed,arrived:[]});renderResult(result);const out=detail.querySelector('#mt-result'),checks=[];append(out,el('p',t('arrived')));result.expected.forEach(item=>{const label=el('label'),input=el('input');input.type='checkbox';input.style.width='auto';checks.push([item,input]);append(label,input,document.createTextNode(' '+item));append(out,label,el('br'));});append(out,button(t('check_delivery'),async()=>{const checked=checks.filter(pair=>pair[1].checked).map(pair=>pair[0]);renderResult(await request('prepare',{id:record.id,kind:'delivery',observed:observed,arrived:checked}));}));}
function confirmDelete(record){detail.textContent='';append(detail,el('h2',t('delete_question')),el('p',record.name),el('p',t('delete_files')),button(common('dialog.delete'),async()=>{await request('delete',{id:record.id,revision:record.revision,confirm:true});await refresh();welcome();say(t('deleted'));},'mt-danger'),button(common('dialog.cancel'),()=>show(record)));}
const heading=el('header');const back=el('a',common('setup.copy.back'),'mt-link');back.href='/chat';append(heading,back);append(heading,el('h1',t('title')),el('p',t('intro')));const toolbar=el('div','','mt-bar');append(toolbar,button(t('add'),()=>{pendingFile=null;form(null);},'mt-primary'),button(common('header.export'),()=>packet('export',{},'my-things.zip')));const settings=el('label',t('title')+' '),toggle=el('input');toggle.type='checkbox';toggle.style.width='auto';toggle.onchange=()=>task(async()=>{const preference=await request('preferences',{enabled:toggle.checked});if(preference.enabled){await refresh();welcome();}else{items=[];selected=null;refreshList();detail.textContent='';say(t('disabled'));}});append(settings,toggle);append(toolbar,settings);append(root,heading,toolbar,status);
const intake=el('section','','mt-card');intake.id='mt-intake';append(intake,el('h2',t('intake')));fileControl(intake,t('receipt_propose'),'receipt',async file=>{const result=await request('propose',{file:file});if(result.reading.state!=='read'){say(t(result.reading.state==='unavailable'?'photo_unavailable':'unreadable'));return;}pendingFile=file;form(result.fields);const evidence=el('pre',result.reading.text);evidence.id='mt-proposal-evidence';prepend(detail,el('p',t('review')),evidence);});fileControl(intake,t('match_photo'),'photo',async file=>{const result=await request('match',{file:file});detail.textContent='';append(detail,el('h2',t(result.state==='match'?'matched':result.state==='choose'?'choose':result.state==='no_match'?'no_match':result.state==='unavailable'?'photo_unavailable':'unreadable')));result.candidates.forEach(candidate=>{const card=el('div','','mt-card');append(card,el('h3',candidate.name),el('pre',candidate.evidence.map(e=>e.saved+' ← '+e.quote).join('\n')),button(t('open'),()=>show(items.find(item=>item.id===candidate.id))),button(t('attach'),async()=>{const chosen=items.find(item=>item.id===candidate.id);const saved=await request('attach',{id:chosen.id,revision:chosen.revision,file:file});await refresh();show(saved.thing);say(t('saved'));}));append(detail,card);});if(result.state==='no_match')append(detail,button(t('add'),()=>form(null)));});
const grid=el('div','','mt-grid'),aside=el('aside','','mt-card');append(aside,el('h2',t('saved_things')),list);append(grid,aside,detail);append(root,intake,el('div','','mt-bar'),grid);task(async()=>{const pref=await request('preferences');toggle.checked=pref.enabled;if(pref.enabled){await refresh();welcome();}else say(t('disabled'));});
window.VoolMyThings=Object.freeze({refresh:refresh});
})();
"""


def render_my_things_fragment() -> str:
    return '<style>' + CSS + '</style><script>' + JS + '</script>'


def render_my_things_page(locale: str) -> str:
    from core.i18n.catalog import catalog_for
    from core.i18n.locales import get_locale
    from core.i18n.page_bundle import render_i18n_bootstrap

    direction = get_locale(locale).direction
    title = html.escape(catalog_for(locale).text('things.title'))
    return ('<!doctype html><html lang="' + html.escape(locale, quote=True) + '" dir="' + direction + '"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title>'
            + render_i18n_bootstrap(locale) + '</head><body class="mt-page"><main id="myThingsRoot"></main>'
            + render_my_things_fragment() + '</body></html>')
